// Layer 2 — Skill analytics. Takes the parsed transactions from
// workflow 33 (Layer 1) and runs them through Ollama 14b with a
// structured prompt to produce a stewardship skill profile.
//
// Per data-dump-to-matched-services spec session note (2026-05-28):
// diagnostic and warm, never judgmental. The user reads the profile back
// and recognizes themselves — strengths AND gaps.
//
// Per EXCELLENCE-STANDARD: religion AND relationship. Structured
// assessment (religion) delivered in warm language (relationship).
// Per TLC firewall: family-private content never leaves NAS; this entire
// workflow runs on Ollama locally.
//
// POST body shape:
//   { transactions: [...], months_of_history?: number, persona_hint?: string }
// Transactions in the shape returned by workflow 33.
//
// Returns:
//   { ok, profile: { budgeting_consistency, tithe_rhythm, debt_posture,
//     buffer_fund_discipline, income_stability, alignment },
//     diagnostic_summary, strengths, gaps_to_consider }

const OLLAMA_BASE = process.env.OLLAMA_BASE_URL || 'http://ollama:11434';
const OLLAMA_MODEL = process.env.OLLAMA_ANALYTICS_MODEL || 'qwen2.5:14b-instruct-q4_K_M';

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const transactions = Array.isArray(body.transactions) ? body.transactions : [];
const monthsOfHistory = parseInt(body.months_of_history || 0, 10);
const personaHint = (body.persona_hint || '').toString();

if (transactions.length === 0) {
  return [{ json: { ok: false, error: 'no transactions provided for analytics' } }];
}

// Compute deterministic stats first. These ground the LLM's narrative.
const totalAmount = transactions.reduce((s, t) => s + (t.amount || 0), 0);
const credits = transactions.filter(t => (t.amount || 0) > 0);
const debits = transactions.filter(t => (t.amount || 0) < 0);
const income = credits.reduce((s, t) => s + t.amount, 0);
const spend = Math.abs(debits.reduce((s, t) => s + t.amount, 0));

// Detect tithe/charitable giving by keyword.
const titheKeywords = /tithe|church|ministry|first[\s-]?fruits|offering|donation|charity|nonprofit/i;
const titheTxns = transactions.filter(t => titheKeywords.test(t.description || ''));
const titheTotal = Math.abs(titheTxns.reduce((s, t) => s + t.amount, 0));
const titheRate = income > 0 ? (titheTotal / income) : 0;

// Detect debt payments by keyword.
const debtKeywords = /loan|mortgage|credit\s?card payment|cc payment|chase\s+card|amex|discover|capital one|student loan|auto loan/i;
const debtTxns = transactions.filter(t => debtKeywords.test(t.description || ''));
const debtTotal = Math.abs(debtTxns.reduce((s, t) => s + t.amount, 0));

// Detect savings/transfers (buffer fund proxy).
const saveKeywords = /transfer|savings|investment|brokerage|vanguard|fidelity|robinhood|emergency fund|buffer/i;
const saveTxns = transactions.filter(t => saveKeywords.test(t.description || ''));
const saveTotal = Math.abs(saveTxns.reduce((s, t) => s + t.amount, 0));

// Date range for context.
const dates = transactions.map(t => t.date).filter(Boolean).sort();
const dateRange = dates.length ? (dates[0] + ' to ' + dates[dates.length - 1]) : '(unknown)';

const stats = {
  transaction_count: transactions.length,
  date_range: dateRange,
  income_total: income.toFixed(2),
  spend_total: spend.toFixed(2),
  net: totalAmount.toFixed(2),
  tithe_total: titheTotal.toFixed(2),
  tithe_count: titheTxns.length,
  tithe_rate_pct: (titheRate * 100).toFixed(1),
  debt_payment_total: debtTotal.toFixed(2),
  debt_payment_count: debtTxns.length,
  savings_transfer_total: saveTotal.toFixed(2),
  savings_transfer_count: saveTxns.length
};

const prompt = `You are the Skill Analytics module for the PoeTech Family OS. You read a household's bank transactions and produce a stewardship skill profile.

Your tone: diagnostic and warm. Never judgmental. The reader is a real family looking at their own money. Speak as a trusted advisor who can see the patterns, name them honestly, and point toward growth without shame.

Religion AND relationship per the EXCELLENCE-STANDARD foundation. Structured assessment (religion) in warm language (relationship).

Return a JSON object with this exact shape:

{
  "profile": {
    "budgeting_consistency": "strong" | "emerging" | "weak",
    "tithe_rhythm": "consistent" | "intermittent" | "absent",
    "debt_posture": "paying_down" | "steady" | "growing" | "none_visible",
    "buffer_fund_discipline": "building" | "steady" | "draining" | "none_visible",
    "income_stability": "steady" | "variable" | "volatile",
    "alignment": "high" | "moderate" | "low"
  },
  "diagnostic_summary": "3-5 sentences. Tell the family what you see. Name strengths first. Then name 1-2 areas worth growing into. Warm tone.",
  "strengths": ["2-3 specific things this family is doing well, named concretely"],
  "gaps_to_consider": ["1-2 areas where the foundation principles suggest there is room to grow. Phrased as invitations not failures."]
}

Ground your assessment in the deterministic stats below — do NOT invent numbers, only interpret these:

${JSON.stringify(stats, null, 2)}

Persona hint (may be empty): ${personaHint || '(none)'}
Months of history declared: ${monthsOfHistory || '(unknown)'}
First 30 transactions for context:
${JSON.stringify(transactions.slice(0, 30).map(t => ({ date: t.date, amount: t.amount, description: (t.description || '').slice(0, 80) })), null, 2)}

Return ONLY the JSON object. No markdown, no preamble, no closing remarks.`;

let profileText = '';
try {
  const r = await fetch(OLLAMA_BASE + '/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: OLLAMA_MODEL, prompt, stream: false, options: { temperature: 0.3, num_predict: 1000 } }),
    signal: AbortSignal.timeout(180000)
  });
  const data = await r.json();
  profileText = (data.response || '').trim();
} catch (e) {
  return [{ json: { ok: false, error: 'ollama call failed: ' + String(e), stats } }];
}

// Try to extract pure JSON from the response (model sometimes wraps in code fences).
let profile = null;
const jsonMatch = profileText.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  try { profile = JSON.parse(jsonMatch[0]); } catch (_) {}
}
if (!profile) {
  return [{ json: { ok: false, error: 'could not parse profile JSON from model output', raw_response: profileText.slice(0, 2000), stats } }];
}

return [{ json: { ok: true, stats, ...profile } }];
